mapper.select:
select distinct sdl.ITEM_CODE id, sdl.ITEM_VALUE text from SYS_DATADICT_LIST sdl inner join SYS_DATADICT_LIST_LINK sdll on sdl.ITEM_CODE = sdll.ITEM_CODE
and sdll.LINKED_DICT_CODE = #{dict_code_parent}
and sdl.DICT_CODE = #{dict_code_child} and sdll.DICT_CODE = #{dict_code_child}
and TRIM(sdll.LINKED_ITEM_CODE) = TRIM(#{item_code_parent})
sdl.ITEM_VALUE like concat(concat('%',#{search}),'%')
ORDER BY sdl.ITEM_CODE asc

SELECT IFNULL(SUM(A.O_AMT),0) FROM BOK_BALANCE A,BOK_SUBJECT B,BOK_BOOKSET C WHERE A.BOOKSET_ID = C.BOOKSET_ID AND B.BOOKSET_ID = C.BOOKSET_ID_TMPL AND A.SUBJECT_NO = B.SUBJECT_NO AND B.BASE_SUBJECT_NATURE = 'XJ' AND A.SUBJECT_LEVEL = '1'
AND A.BOOKSET_ID in
#{item}
AND DATE_FORMAT(A.BALANCE_DATE,'%Y-%m-%d') = #{mdate,jdbcType=VARCHAR}

SELECT IFNULL(SUM(A.O_AMT),0) FROM BOK_BALANCE A,BOK_SUBJECT B,BOK_BOOKSET C WHERE A.BOOKSET_ID = C.BOOKSET_ID AND B.BOOKSET_ID = C.BOOKSET_ID_TMPL AND A.SUBJECT_NO = B.SUBJECT_NO AND B.BASE_SUBJECT_NATURE = 'XJ' AND A.SUBJECT_LEVEL = '1'
AND A.BOOKSET_ID in
#{item}
AND DATE_FORMAT(A.BALANCE_DATE,'%Y-%m-%d') = #{mdate,jdbcType=VARCHAR}

SELECT IFNULL(SUM(A.O_HAPPEN_AMT),0) FROM TRD_VOUCH_DEAL_DETAIL A,BOK_SUBJECT B,BOK_BOOKSET C,TRD_VOUCH_DEAL D WHERE 1=1
AND A.BOOKSET_ID in
#{item}
AND C.BOOKSET_ID = A.BOOKSET_ID AND B.BOOKSET_ID = C.BOOKSET_ID_TMPL AND A.SUBJECT_NO = B.SUBJECT_NO AND B.BASE_SUBJECT_NATURE = 'XJ' AND D.TRADE_ID = A.TRADE_ID AND A.CD_FLAG = #{crdrFlg,jdbcType=VARCHAR} AND DATE_FORMAT(D.BOOK_DATE,'%Y-%m-%d') >= #{vdate,jdbcType=VARCHAR} AND DATE_FORMAT(D.BOOK_DATE,'%Y-%m-%d') <= #{mdate,jdbcType=VARCHAR}

select
(case when jx.trantype = '752' then 'F14' when jx.trantype = '751' then 'F14' when jx.trantype = '300' then 'F11' when jx.trantype = '410' then 'F12' when jx.trantype = '761' then 'F34' when jx.trantype = '760' then 'F34' when jx.trantype = '200' then 'F10' when jx.trantype = '100' then 'F10' when jx.trantype = '107' then 'F10' when jx.trantype = '105' then 'F10' when jx.trantype = '108' then 'F10' when jx.trantype = '103' then 'F10' when jx.trantype = '104' then 'F10' end) as finprodType, jx.tanum as tradeId, jx.settledate as settleDate, jx.trantype as ps, (case when jx.trantype = '761' then jx.currencycode2 else jx.currencycode end) as tradeCcy, jx.fxrate as fxrate, CASE WHEN jx.trantype in ('300','410','200','100','107','105','108','103','104') THEN jx.cash WHEN jx.trantype = '760' THEN jx.PRINCIPAL WHEN jx.trantype = '761' THEN jx.CASH2 ELSE 0 END as buyTradeAmt, CASE WHEN jx.trantype IN ('752','751') THEN jx.intatmat ELSE 0 END as recInt, (case when jx.trantype = '761' then jx.currencycode else jx.currencycode2 end) AS sellCcy, jx.fxrate2 as fxrate2, CASE WHEN jx.trantype IN ('752','751') THEN jx.intatmat2 ELSE 0 END as payInt, CASE WHEN jx.trantype IN ('300','410') THEN jx.cash2 WHEN jx.trantype = '760' THEN jx.PRINCIPAL2 WHEN jx.trantype = '761' THEN jx.CASH ELSE 0 END as sellTradeAmt from JXT_TRAN_BASIC jx where jx.post_status = 'P' and jx.trantype in ('752','751','300','410','761','760','200','100','107','105','108','103') and jx.settledate >= STR_TO_DATE(#{vdate},'%Y-%m-%d') and jx.settledate <= STR_TO_DATE(#{mdate},'%Y-%m-%d') and exists ( select bookset_id, busi_no, busi_table, bookset_date, book_date, happen_date, is_accounted, book_id, create_user, create_dept, create_time, update_user, update_time, inv_aim, inv_aim_method from BOK_DEAL_ACCOUNTING acct where acct.busi_no = jx.tanum AND acct.BOOKSET_ID in
#{item}
)

select quot_unit quoUnit from MST_EXCHARGE_QUOTE where basis_cyy in
#{item}
and quot_cyy = #{bCcy} and trade_date <= STR_TO_DATE(#{vdate},'%Y-%m-%d') and trade_date >= STR_TO_DATE(#{mdate},'%Y-%m-%d')
